            const dimension = nonTieredDimensionsMap[dimensionId];
            const totalNum = parseFloat(dimensionTotals[dimensionId] as unknown as string);
            // Determine billable quantity respecting allowance and overage rules
            let billableQuantity: number;
            const entitlement = dimension.usageEntitlement as unknown;
            if (entitlement !== undefined && entitlement !== null) {
                if (entitlement === 'inf') {
                    billableQuantity = 0;
                } else {
                    const entNum = typeof entitlement === 'string' ? parseFloat(entitlement as string) : (entitlement as number);
                    if (totalNum <= entNum) {
                        billableQuantity = 0;
                    } else if (dimension.overageAllowed !== 'true' && (dimension.overageAllowed as unknown) !== 'True' && dimension.overageAllowed !== 'TRUE') {
                        // overage not permitted (undefined, false, etc.)
                        // Need to compare to enum value 'true' - handle both string and enum
                        const overage = dimension.overageAllowed as unknown as string;
                        if (overage !== 'true') {
                            billableQuantity = 0;
                        } else {
                            billableQuantity = totalNum - entNum;
                        }
                    } else {
                        billableQuantity = totalNum - entNum;
                    }
                    // More robust: if overageAllowed is not exactly 'true', no charge
                    if (billableQuantity !== 0 && dimension.overageAllowed !== 'true') {
                        // re-evaluate: only true allows overage
                        const overageStr = String(dimension.overageAllowed);
                        if (overageStr !== 'true') {
                            billableQuantity = 0;
                        }
                    }
                }
            } else {
                billableQuantity = totalNum;
            }

            // If nothing owed, skip dimension
            if (!billableQuantity || billableQuantity <= 0) {
                return;
            }

            // Handle free (zero-priced) dimensions according to invoice settings
            const consumptionPriceStr = dimension.consumptionPrice as unknown as string | undefined;
            const priceNum = consumptionPriceStr !== undefined && consumptionPriceStr !== null && consumptionPriceStr !== '' ? parseFloat(consumptionPriceStr) : 0;
            const isFree = priceNum === 0;
            if (isFree) {
                const freeSetting = offeringInstance.settings?.freeDimensionOnInvoice as unknown as string;
                if (freeSetting === FreeDimensionOnInvoice.hide || freeSetting === 'hide') {
                    return;
                }
            }

            let unitCost = Number(
                (priceNum * exchangeRate).toFixed(
                    Offering.getDecimalsForNumber(priceNum) === 0 ? 2 : Offering.getDecimalsForNumber(priceNum),
                ),
            );
            if (dimension?.paymentSchedule === PaymentSchedule.upfront) {
                const billingMSStartDate = proratedStartDate ? proratedStartDate : startDate;
                const billingMSSeconds: number = Math.round(Math.abs(endDate.getTime() - billingMSStartDate.getTime()));
                const billingMSSecondsInBillingCycle = Offering.determineBillingSecondsInBillingCycle({
                    date: billingMSStartDate,
                    billingCycle: offeringInstance?.billingCycle,
                }) as number;
                unitCost = Math.round(100 * unitCost * (billingMSSeconds / billingMSSecondsInBillingCycle)) / 100;
            }
            const {
                usageIncrement,
                consumptionUnit: { unit, type },
            } = dimension;
            const { displayName, total: displayTotal } = InvoiceLineItem.prepareLineItem({
                total: billableQuantity,
                dimensionType: type,
                dimensionId,
                dimensionName: dimension.dimensionName,
                offeringName: offeringInstance.offeringName,
                usageIncrement: parseInt(usageIncrement),
                dimensionUnit: unit,
                negative,
            });
            lineItems.addLineItem(new InvoiceLineItem(displayName, displayTotal, unitCost));
        });`;

if (!content.includes(oldBlock)) {
  console.error("Old block not found!");
  // debug
  console.log(content.slice(content.indexOf('Object.keys(dimensionTotals)'), content.indexOf('Object.keys(dimensionTotals)')+2000));
  process.exit(1);
}

content = content.replace(oldBlock, newBlock);

fs.writeFileSync(path, content);
console.log("Patch applied");
