cat > /tmp/final_verify.ts <<'TS'
import { InvoiceLineGathererService } from "/app/src/microservices/invoiceLineGatherer/invoiceLineGatherer.service.js";
async function main(){
  const svc = new InvoiceLineGathererService();
  const ridge = await svc.gatherInvoiceLines({businessID:"biz-ridge", catalogueBucket:"meteringco-billing-sandbox", catalogueKey:"catalogues/biz-ridge-2026-07.json"});
  const vale = await svc.gatherInvoiceLines({businessID:"biz-vale", catalogueBucket:"meteringco-billing-sandbox", catalogueKey:"catalogues/biz-vale-2026-07.json"});
  // Expected per spec:
  // Ridge alpha: api-calls 100 @0.01, seats 2 @10 (12-10), no alerts (free hide), no reports (forbid), no storage (inf)
  // Ridge bravo: jobs 200 @0.05, minutes 0 (unexhausted), scans 0 (inf), tasks 0 (forbid)
  // Vale charlie: messages 50 @0.01, hours 10 @0 (free show), units 5 @5 (25-20)
  console.log("RIDGE:", JSON.stringify(ridge,null,2));
  console.log("VALE:", JSON.stringify(vale,null,2));
  // Assertions
  const alpha = ridge.find(r=>r.customerId==="cus_sample_alpha");
  const bravo = ridge.find(r=>r.customerId==="cus_sample_bravo");
  const charlie = vale.find(r=>r.customerId==="cus_sample_charlie");
  function assert(cond, msg){ if(!cond){ console.error("ASSERT FAIL:",msg); process.exit(1);} }
  assert(alpha.lineItems.length===2, "alpha should have 2 lines");
  assert(alpha.lineItems.some(l=>l.name.includes("Ridge API Calls") && l.quantity===100 && l.unitCost===0.01), "alpha api calls");
  assert(alpha.lineItems.some(l=>l.name.includes("Ridge Seats") && l.quantity===2 && l.unitCost===10), "alpha seats");
  assert(!alpha.lineItems.some(l=>l.name.includes("Ridge Alerts")), "alpha alerts hidden");
  assert(!alpha.lineItems.some(l=>l.name.includes("Ridge Reports")), "alpha reports forbidden");
  assert(!alpha.lineItems.some(l=>l.name.includes("Ridge Storage")), "alpha storage inf");
  assert(bravo.lineItems.length===1, "bravo 1 line");
  assert(bravo.lineItems[0].name.includes("Ridge Jobs") && bravo.lineItems[0].quantity===200 && bravo.lineItems[0].unitCost===0.05, "bravo jobs");
  assert(charlie.lineItems.length===3, "charlie 3 lines");
  assert(charlie.lineItems.some(l=>l.name.includes("Vale Messages") && l.quantity===50), "vale messages");
  assert(charlie.lineItems.some(l=>l.name.includes("Vale Hours") && l.quantity===10 && l.unitCost===0), "vale hours");
  assert(charlie.lineItems.some(l=>l.name.includes("Vale Units") && l.quantity===5 && l.unitCost===5), "vale units");
  console.log("ALL ASSERTS PASSED");
}
main().catch(e=>{console.error(e);process.exit(1)});
TS
npx tsx /tmp/final_verify.ts 2>&1

